## SPDX-License-Identifier: Apache-2.0 OR GPL-2.0-or-later

import unittest

import scripts_path # pylint: disable=unused-import
from mbedtls_framework import test_config_checks_generator


class MbedtlsTestConfigChecks(test_config_checks_generator.TestConfigChecks):
    """Mbed TLS unit tests for checks generated by config_checks_generator."""

    #pylint: disable=invalid-name # uppercase letters make sense here

    PROJECT_CONFIG_C = 'library/mbedtls_config.c'
    PROJECT_SPECIFIC_INCLUDE_DIRECTORIES = [
        'tf-psa-crypto/include',
        'tf-psa-crypto/drivers/builtin/include',
    ]

    def test_crypto_no_fs_io(self) -> None:
        """A sample error expected from crypto's check_config.h."""
        self.bad_case('#undef MBEDTLS_FS_IO',
                      error=('MBEDTLS_PSA_ITS_FILE_C'))

    def test_mbedtls_no_tls12(self) -> None:
        """A sample error expected from check_config.h."""
        self.bad_case(None,
                      '''
                      #undef MBEDTLS_SSL_PROTO_TLS1_2
                      #define MBEDTLS_SSL_RENEGOTIATION
                      ''',
                      error=('MBEDTLS_SSL_RENEGOTIATION'))

    def test_crypto_define_MBEDTLS_USE_PSA_CRYPTO(self) -> None:
        self.bad_case('#define MBEDTLS_USE_PSA_CRYPTO',
                      error=('MBEDTLS_USE_PSA_CRYPTO is no longer supported' +
                             '.*always on'))

    def test_crypto_undef_MBEDTLS_USE_PSA_CRYPTO(self) -> None:
        self.bad_case('#undef MBEDTLS_USE_PSA_CRYPTO',
                      error=('MBEDTLS_USE_PSA_CRYPTO is no longer supported' +
                             '.*always on'))

    def test_crypto_exempt_define_MBEDTLS_USE_PSA_CRYPTO(self) -> None:
        self.good_case('#define MBEDTLS_USE_PSA_CRYPTO',
                       extra_options=['-DMBEDTLS_CONFIG_CHECK_ALLOW_REMOVED_OPTIONS'])

    def test_crypto_exempt_undef_MBEDTLS_USE_PSA_CRYPTO(self) -> None:
        self.good_case('#undef MBEDTLS_USE_PSA_CRYPTO',
                       extra_options=['-DMBEDTLS_CONFIG_CHECK_ALLOW_REMOVED_OPTIONS'])


if __name__ == '__main__':
    unittest.main()
